            "BUS003": {"id": "BUS003", "name": "Mercedes Luxury 06:00 AM", "route": "Bangalore to Chennai", "departure": "06:00", "arrival": "12:00", "fare": 1200.00, "total_seats": 36},
            "BUS004": {"id": "BUS004", "name": "Ashok Leyland Seater 10:00 AM", "route": "Bangalore to Chennai", "departure": "10:00", "arrival": "16:00", "fare": 750.00, "total_seats": 50},
