DB = _Store()
_SESSION = {
    "logged_in": False,
    "user_email": None,
    "page": "Login Page",
    "message": "",
    "search_results": [],
    "selected_bus_id": None,
    "selected_seat": None,
    "passenger_details": None,
    "travel_date": None,
    "last_booking_pnr": None
}


def _generate_seat_map(bus_id, total_seats):
    """Generate seat numbers for a bus."""
    seats = []
    # Generate enough rows to cover all seats, with 4 seats per row
    # Also ensure we generate enough to cover any pre-booked seats
    max_row_needed = (total_seats + 3) // 4

    # Check if there are any pre-booked seats for this bus that might need higher row numbers
    for (bid, seat_num) in DB.booked_seats.keys():
        if bid == bus_id:
            # Extract row number from seat (e.g., "15B" -> 15)
            row_num = int(''.join(filter(str.isdigit, seat_num)))
            max_row_needed = max(max_row_needed, row_num)

    seat_count = 0
    for row in range(1, max_row_needed + 1):
        for col in ['A', 'B', 'C', 'D']:
            seat_num = f"{row}{col}"
            seats.append(seat_num)
            seat_count += 1
            if seat_count >= total_seats:
                break
        if seat_count >= total_seats:
            break

    return seats


def _time_to_minutes(time_str):
    """Convert time string HH:MM to minutes since midnight for comparison."""
    parts = time_str.split(':')
    return int(parts[0]) * 60 + int(parts[1])


class UI:
    """UI-layer actions - what the user does and sees in the portal."""

    @staticmethod
    def current_page():
        """Returns the exact page name from the pages list that user is currently on."""
        return _SESSION["page"]

    @staticmethod
    def visible_message():
        """Returns the current error, success, or info message displayed on screen."""
        return _SESSION["message"]

    @staticmethod
    def navigate_to_login():
        """Navigates to Login Page. Clears any visible message."""
        _SESSION["page"] = "Login Page"
        _SESSION["message"] = ""

    @staticmethod
    def login(email, password):
        """Attempts to log in with provided credentials."""
        user = DB.users.get(email)
        if user and user["password"] == password:
            _SESSION["logged_in"] = True
            _SESSION["user_email"] = email
            _SESSION["page"] = "Search Page"
            _SESSION["message"] = ""
            return True
        else:
            _SESSION["message"] = "Invalid email or password. Please try again."
            _SESSION["page"] = "Login Page"
            return False

    @staticmethod
    def search_buses(source, destination, travel_date):
        """Validates travel_date and searches for buses matching route and date."""
        if travel_date < CONFIG["current_date"]:
            _SESSION["message"] = "Please select a current or future date."
            return False

        route = f"{source} to {destination}"
        results = []
        current_time_minutes = _time_to_minutes(CONFIG["current_time"])

        for bus in DB.buses.values():
            if bus["route"] == route:
                # Filter by time if same-day travel
                if travel_date == CONFIG["current_date"]:
                    bus_time_minutes = _time_to_minutes(bus["departure"])
                    if bus_time_minutes >= current_time_minutes:
                        results.append(bus)
                else:
                    results.append(bus)

        _SESSION["search_results"] = results
        _SESSION["travel_date"] = travel_date

        if results:
            _SESSION["page"] = "Search Results Page"
            _SESSION["message"] = ""
            return True
        else:
            _SESSION["message"] = "No buses available for this route on the selected date."
            return True

    @staticmethod
    def get_search_results():
        """Returns list of buses from last search."""
        if _SESSION["page"] != "Search Results Page":
            return []
        return [{"bus_id": b["id"], "name": b["name"], "route": b["route"], 
                 "departure": b["departure"], "arrival": b["arrival"], "fare": b["fare"]} 
                for b in _SESSION["search_results"]]

    @staticmethod
    def select_bus(bus_name):
        """Selects bus by name from search results."""
        for bus in _SESSION["search_results"]:
            if bus["name"] == bus_name:
                _SESSION["selected_bus_id"] = bus["id"]
                _SESSION["page"] = "Seat Selection Page"
                _SESSION["message"] = ""
                return True
        _SESSION["message"] = "Bus not found in search results."
        return False

    @staticmethod
    def get_seat_map():
        """Returns seat map for currently selected bus."""
        if _SESSION["page"] != "Seat Selection Page" or not _SESSION["selected_bus_id"]:
            return []

        bus = DB.buses[_SESSION["selected_bus_id"]]
        all_seats = _generate_seat_map(bus["id"], bus["total_seats"])

        seat_map = []
        for seat_num in all_seats:
            if (bus["id"], seat_num) in DB.booked_seats:
                seat_map.append({"seat_number": seat_num, "status": "occupied"})
            else:
                seat_map.append({"seat_number": seat_num, "status": "available"})

        return seat_map

    @staticmethod
    def select_seat(seat_number):
        """Attempts to select seat."""
        if not _SESSION["selected_bus_id"]:
            return False

        bus = DB.buses[_SESSION["selected_bus_id"]]

        # Check if seat is already booked first
        if (bus["id"], seat_number) in DB.booked_seats:
            _SESSION["message"] = "Seat already booked"
            return False

        # Then check if seat exists
        all_seats = _generate_seat_map(bus["id"], bus["total_seats"])
        if seat_number not in all_seats:
            _SESSION["message"] = "Invalid seat number."
            return False

        _SESSION["selected_seat"] = seat_number
        _SESSION["page"] = "Passenger Details Page"
        _SESSION["message"] = ""
        return True

    @staticmethod
    def enter_passenger_details(passenger_name, age, gender, contact):
        """Validates and stores passenger details."""
        if not passenger_name or passenger_name.strip() == "":
            _SESSION["message"] = "Passenger name is required."
            return False

        if age < 1 or age > 120:
            _SESSION["message"] = "Age must be between 1 and 120."
            return False

        if not (isinstance(contact, str) and contact.isdigit() and len(contact) == 10):
            _SESSION["message"] = "Please enter a valid 10-digit mobile number."
            return False

        _SESSION["passenger_details"] = {
            "passenger_name": passenger_name,
            "age": age,
            "gender": gender,
            "contact": contact
        }
        _SESSION["page"] = "Payment Page"
        _SESSION["message"] = ""
        return True

    @staticmethod
    def make_payment(card_number, cvv, expiry):
        """Validates card and processes payment."""
        card = DB.cards.get(card_number)

        if not card:
            _SESSION["message"] = "Invalid card details."
            return False

        bus = DB.buses[_SESSION["selected_bus_id"]]
        fare = bus["fare"]

        if card["balance"] < fare:
            _SESSION["message"] = "Payment declined due to insufficient funds."
            return False

        # Process payment
        card["balance"] -= fare
        pnr = DB.generate_pnr()

        booking = {
            "pnr": pnr,
            "bus_id": bus["id"],
            "seat_number": _SESSION["selected_seat"],
            "passenger_name": _SESSION["passenger_details"]["passenger_name"],
            "age": _SESSION["passenger_details"]["age"],
            "gender": _SESSION["passenger_details"]["gender"],
            "contact": _SESSION["passenger_details"]["contact"],
            "travel_date": _SESSION["travel_date"],
            "fare": fare,
            "status": "Confirmed"
        }

        DB.bookings[pnr] = booking
        DB.booked_seats[(bus["id"], _SESSION["selected_seat"])] = {
            "bus_id": bus["id"],
            "seat_number": _SESSION["selected_seat"],
            "booking_id": pnr,
            "passenger_name": _SESSION["passenger_details"]["passenger_name"],
            "status": "booked"
        }

        _SESSION["last_booking_pnr"] = pnr
        _SESSION["page"] = "Booking Confirmation Page"
        _SESSION["message"] = ""
        return True

    @staticmethod
    def get_booking_confirmation():
        """Returns booking details if on Booking Confirmation Page."""
        if _SESSION["page"] != "Booking Confirmation Page" or not _SESSION["last_booking_pnr"]:
            return None

        booking = DB.bookings.get(_SESSION["last_booking_pnr"])
        if not booking:
            return None

        bus = DB.buses[booking["bus_id"]]

        return {
            "pnr": booking["pnr"],
            "passenger_name": booking["passenger_name"],
            "seat_number": booking["seat_number"],
            "bus_name": bus["name"],
            "travel_date": booking["travel_date"],
            "route": bus["route"],
            "status": booking["status"]
        }


class API:
    """API-layer actions."""

    @staticmethod
    def api_login(email, password):
        """Authenticates user."""
        user = DB.users.get(email)
        if user and user["password"] == password:
            return {"ok": True, "user_email": email}
        else:
            return {"ok": False, "error": "Invalid email or password. Please try again."}

    @staticmethod
    def api_search_buses(source, destination, travel_date):
        """Validates travel_date and searches buses matching route."""
        if travel_date < CONFIG["current_date"]:
            return {"ok": False, "error": "Please select a current or future date."}

        route = f"{source} to {destination}"
        results = []
        current_time_minutes = _time_to_minutes(CONFIG["current_time"])

        for bus in DB.buses.values():
            if bus["route"] == route:
                if travel_date == CONFIG["current_date"]:
                    bus_time_minutes = _time_to_minutes(bus["departure"])
                    if bus_time_minutes >= current_time_minutes:
                        results.append({"bus_id": bus["id"], "name": bus["name"], "route": bus["route"],
                                      "departure": bus["departure"], "arrival": bus["arrival"], "fare": bus["fare"]})
                else:
                    results.append({"bus_id": bus["id"], "name": bus["name"], "route": bus["route"],
                                  "departure": bus["departure"], "arrival": bus["arrival"], "fare": bus["fare"]})

        return {"ok": True, "buses": results}

    @staticmethod
    def api_get_seats(bus_id):
        """Returns seat map for bus."""
        bus = DB.buses.get(bus_id)
        if not bus:
            return {"ok": False, "error": "Bus not found."}

        all_seats = _generate_seat_map(bus_id, bus["total_seats"])
        seats = []
        for seat_num in all_seats:
            if (bus_id, seat_num) in DB.booked_seats:
                seats.append({"seat_number": seat_num, "status": "occupied"})
            else:
                seats.append({"seat_number": seat_num, "status": "available"})

        return {"ok": True, "seats": seats}

    @staticmethod
    def api_book_ticket(bus_id, seat_number, passenger_name, age, gender, contact, card_number, cvv, expiry, travel_date):
        """Validates all inputs and creates booking."""
        # Validate passenger_name
        if not passenger_name or passenger_name.strip() == "":
            return {"ok": False, "error": "Passenger name is required."}

        # Validate age
        if age < 1 or age > 120:
            return {"ok": False, "error": "Age must be between 1 and 120."}

        # Validate contact
        if not (isinstance(contact, str) and contact.isdigit() and len(contact) == 10):
            return {"ok": False, "error": "Please enter a valid 10-digit mobile number."}

        # Validate bus exists
        bus = DB.buses.get(bus_id)
        if not bus:
            return {"ok": False, "error": "Bus not found."}

        # Check if seat is already booked first
        if (bus_id, seat_number) in DB.booked_seats:
            return {"ok": False, "error": "Seat already booked"}

        # Validate seat exists
        all_seats = _generate_seat_map(bus_id, bus["total_seats"])
        if seat_number not in all_seats:
            return {"ok": False, "error": "Invalid seat number."}

        # Validate card
        card = DB.cards.get(card_number)
        if not card:
            return {"ok": False, "error": "Invalid card details."}

        if card["balance"] < bus["fare"]:
            return {"ok": False, "error": "Payment declined due to insufficient funds."}

        # Process booking
        card["balance"] -= bus["fare"]
        pnr = DB.generate_pnr()

        booking = {
            "pnr": pnr,
            "bus_id": bus_id,
            "seat_number": seat_number,
            "passenger_name": passenger_name,
            "age": age,
            "gender": gender,
            "contact": contact,
            "travel_date": travel_date,
            "fare": bus["fare"],
            "status": "Confirmed"
        }

        DB.bookings[pnr] = booking
        DB.booked_seats[(bus_id, seat_number)] = {
            "bus_id": bus_id,
            "seat_number": seat_number,
            "booking_id": pnr,
            "passenger_name": passenger_name,
            "status": "booked"
        }

        return {
            "ok": True,
            "booking": {
                "pnr": pnr,
                "passenger_name": passenger_name,
                "seat_number": seat_number,
                "bus_name": bus["name"],
                "travel_date": travel_date,
                "route": bus["route"],
                "status": "Confirmed",
                "fare": bus["fare"]
            }
        }


class Database:
    """Direct DB-layer access, for verifying what was really stored."""

    @staticmethod
    def db_get_user(email):
        """Returns user record if email exists, None otherwise."""
        user = DB.users.get(email)
        return dict(user) if user else None

    @staticmethod
    def db_get_bus(bus_id):
        """Returns bus record if bus_id exists, None otherwise."""
        bus = DB.buses.get(bus_id)
        return dict(bus) if bus else None

    @staticmethod
    def db_get_booking(pnr):
        """Returns booking record if pnr exists, None otherwise."""
        booking = DB.bookings.get(pnr)
        return dict(booking) if booking else None

    @staticmethod
    def db_get_booked_seats(bus_id):
        """Returns list of seat numbers currently booked for the bus_id."""
        seats = []
        for (bid, seat_num), _ in DB.booked_seats.items():
            if bid == bus_id:
                seats.append(seat_num)
        return seats

    @staticmethod
    def db_get_card_balance(card_number):
        """Returns current balance for card if card exists, None otherwise."""
        card = DB.cards.get(card_number)
        return card["balance"] if card else None

    @staticmethod
    def db_delete_booking(pnr):
        """Deletes booking record and frees the seat."""
        booking = DB.bookings.pop(pnr, None)
        if booking:
            key = (booking["bus_id"], booking["seat_number"])
            DB.booked_seats.pop(key, None)
            return True
        return False


def setup():
    """Resets app to initial state."""
    DB.reset()
    _SESSION.update({
        "logged_in": False,
        "user_email": None,
        "page": "Login Page",
        "message": "",
        "search_results": [],
        "selected_bus_id": None,
        "selected_seat": None,
        "passenger_details": None,
        "travel_date": None,
        "last_booking_pnr": None
    })


def teardown(booking_id=None):
    """If booking_id is provided and exists, deletes that booking and frees its seat."""
    if booking_id is not None:
        Database.db_delete_booking(booking_id)


